function weakStats(){
 const map=new Map();
 for(const ev of state.events||[]){
   if(!['lesson','practice','grammar','diagnostic'].includes(ev.type))continue;
   if(ev.source==='errors'||ev.source==='writing-completion'||ev.source==='adaptive')continue;
   for(const x of ev.items||[]){
    if(x.correct!==false)continue;
    const topic=x.topic||ev.topic||'',domain=x.domain||'';
    if(!topic||!domain)continue;
    const key=domain+'|'+topic;const old=map.get(key)||{key,domain,topic,count:0,last:'',weeks:new Set()};
    old.count++;if((ev.date||'')>old.last)old.last=ev.date||'';
    if(ev.week)old.weeks.add(ev.week);
    map.set(key,old);
   }
 }
 for(const x of map.values()){
   const clear=(state.events||[]).some(e=>e.type==='practice'&&e.source==='adaptive'&&e.topic===x.topic&&e.domain===x.domain&&e.passed&&(e.date||'')>x.last);
   x.resolved=clear;
 }
 return [...map.values()].filter(x=>x.count>=2&&!x.resolved).sort((a,b)=>b.count-a.count);
}
function adaptiveDeck(){
 if(!COACH)return [];
 const result=[];
 for(const g of weakStats().slice(0,6)){
   let qs=[];
   if(g.domain==='Грамматика'){
     for(let wi=0;wi<P.weeks.length;wi++)qs.push(...COACH.makeExtra(wi).filter(q=>q.studyTopic===g.topic));
     if(!qs.length){
       const matching=P.grammarGroups.flatMap(x=>x.topics).find(x=>x.title===g.topic);
       const rule=matching&&P.rules[g.topic];
       if(rule)qs=rule.check.map((q,i)=>({id:'supp-rule-'+g.topic+'-'+i,question:q[0],answer:q[1],options:q[2],explain:rule.tip,studyTopic:g.topic,domain:g.domain}));
     }
   }else if(g.domain==='Словарь'){
     for(let wi=0;wi<P.weeks.length&&!qs.length;wi++)for(let si=0;si<3&&!qs.length;si++)qs=COACH.vocabQuestions(wi,si).filter(q=>q.studyTopic===g.topic);
   }
   if(qs.length)result.push({...g,questions:qs.slice(0,4)});
 }
 return result;
}
